function readObservations(input) {
  const { previous, current } = input ?? {};
  const validPeriod = period => (
    period && Number.isInteger(period.mathScore) && period.mathScore >= 0 && period.mathScore <= 100
    && Number.isInteger(period.attendedDays) && period.attendedDays >= 0 && period.attendedDays <= 5
  );

  if (!validPeriod(previous) || !validPeriod(current)) {
    throw new RangeError('Each period requires a whole math score from 0 to 100 and attendance from 0 to 5 days.');
  }

  const period = ({ mathScore, attendedDays }) => ({ mathScore, attendedDays });
  return { previous: period(previous), current: period(current) };
}

function detectRisk(input) {
  const { previous, current } = readObservations(input);
  const mathChange = current.mathScore - previous.mathScore;
  const attendanceChange = current.attendedDays - previous.attendedDays;
  const mathWarning = mathChange <= -15;
  const attendanceWarning = attendanceChange <= -2;
  const risk = mathWarning && attendanceWarning ? 'high' : mathWarning || attendanceWarning ? 'watch' : 'low';

  return { risk, mathChange, attendanceChange };
}

function readDiagnosisEvidence(input, attendedDays) {
  if (input != null && (typeof input !== 'object' || Array.isArray(input))) {
    throw new RangeError('Evidence must be a JSON object.');
  }

  const { fractionQuiz = null, lateBusOnAbsenceDays = null } = input ?? {};
  let quiz = null;
  if (fractionQuiz !== null) {
    const { correct, total } = fractionQuiz;
    if (!Number.isInteger(total) || total < 1 || total > 100 ||
      !Number.isInteger(correct) || correct < 0 || correct > total) {
      throw new RangeError('Fraction quiz requires a total from 1 to 100 and a correct count from 0 to the total.');
    }
    quiz = { correct, total };
  }

  if (lateBusOnAbsenceDays !== null && (!Number.isInteger(lateBusOnAbsenceDays) ||
    lateBusOnAbsenceDays < 0 || lateBusOnAbsenceDays > 5 - attendedDays)) {
    throw new RangeError('Bus delay days must be within the current absence count.');
  }

  return { fractionQuiz: quiz, lateBusOnAbsenceDays };
}
function readCheckpoints(input, current, normalize) {
  const checkpoints = input.checkpoints ?? (input.weekTwo == null ? [] : [input.weekTwo]);
  if (!Array.isArray(checkpoints) || checkpoints.length > 7) {
    throw new RangeError('Provide at most seven weekly measurements, in order from week two.');
  }
  return checkpoints.map(week => normalize({ previous: current, current: week }).current);
}

const input = $input.first().json.body;
try {
  const body = detectRisk(input);
  const evidence = readDiagnosisEvidence(input.evidence, input.current.attendedDays);
  const current = readObservations(input).current;
  const checkpoints = readCheckpoints(input, current, readObservations);
  return [{ json: { statusCode: 200, body, evidence, current, checkpoints } }];
} catch (error) {
  if (!(error instanceof RangeError)) throw error;
  return [{ json: { statusCode: 422, body: { error: "INVALID_OBSERVATIONS", message: error.message } } }];
}

function diagnoseCase(detection, evidence) {
  if (detection.risk === 'low') return { learning: 'skipped', transport: 'skipped' };

  const quiz = evidence.fractionQuiz;
  let learning = 'unknown';
  if (quiz) learning = quiz.correct * 5 < quiz.total * 3 ? 'fractions' : 'no-signal';

  const bus = evidence.lateBusOnAbsenceDays;
  let transport = 'unknown';
  if (bus !== null) transport = detection.attendanceChange < 0 && bus > 0 ? 'possible-factor' : 'no-signal';

  return { learning, transport };
}

const data = $input.first().json;
if (data.statusCode === 200) data.body.diagnosis = diagnoseCase(data.body, data.evidence);
return [{ json: data }];

function planIntervention(diagnosis) {
  if (diagnosis.learning === 'skipped') return { focus: 'monitor', sessions: 0, minutes: 0 };
  if (diagnosis.learning === 'fractions') return { focus: 'fractions', sessions: 3, minutes: 20 };
  return { focus: 'review', sessions: 1, minutes: 15 };
}
function prioritizeSupport(detection, diagnosis) {
  if (detection.risk !== 'high') return [];
  const priorities = ['teacher-check-in'];
  priorities.push(diagnosis.learning === 'fractions' ? 'fraction-practice' : 'math-check');
  if (detection.attendanceChange < 0) priorities.push('attendance-check');
  if (diagnosis.transport === 'possible-factor') priorities.push('transport-check');
  priorities.push('weekly-review');
  return priorities;
}
const data = $input.first().json;
if (data.statusCode === 200) {
  data.body.plan = planIntervention(data.body.diagnosis);
  data.body.support = prioritizeSupport(data.body, data.body.diagnosis);
}
return [{ json: data }];

function chooseResources(plan) {
  return plan.focus === 'fractions' ? ['fraction-video', 'fraction-practice']
    : plan.focus === 'review' ? ['review-checklist'] : [];
}
const data = $input.first().json;
if (data.statusCode === 200) data.body.resources = chooseResources(data.body.plan);
return [{ json: data }];

function evaluateFollowup(focus, baseline, previous, measurement) {
  const { mathScore, attendedDays } = measurement;
  let next = focus;
  if (attendedDays >= 4) {
    if (focus === 'fractions' && mathScore >= 70 && mathScore - baseline.mathScore >= 10) next = 'word-problems';
    if (focus === 'word-problems') {
      if (mathScore < 70) next = 'fractions';
      else if (mathScore >= 78 && previous.mathScore >= 75) next = 'mixed-review';
    }
    if (focus === 'mixed-review') {
      if (mathScore < 75) next = 'word-problems';
      else if (mathScore >= 85) next = 'independent';
    }
    if (focus === 'independent' && mathScore < 80) next = 'mixed-review';
  }
  return {
    ...measurement,
    mathChange: mathScore - baseline.mathScore,
    attendanceChange: attendedDays - baseline.attendedDays,
    focus: next,
  };
}
function buildRoadmap(plan, baseline, checkpoints) {
  const projected = ['fractions', 'fractions', 'word-problems', 'word-problems', 'word-problems',
    'mixed-review', 'mixed-review', 'independent'];
  const mathTargets = [60, 68, 72, 74, 76, 78, 82, 85];
  const weeks = [];
  let focus = plan.focus;
  let previous = baseline;
  let evaluation = null;
  for (let index = 0; index < 8; index++) {
    const measurement = index === 0 ? baseline : checkpoints[index - 1] ?? null;
    const scheduledFocus = index > checkpoints.length + 1 && plan.focus === 'fractions' ? projected[index] : focus;
    const shorter = scheduledFocus === 'mixed-review' || scheduledFocus === 'independent';
    const sessions = shorter ? (scheduledFocus === 'mixed-review' ? 2 : 1) : plan.sessions;
    const minutes = scheduledFocus === 'independent' ? 15 : plan.minutes;
    weeks.push({
      week: index + 1,
      focus: scheduledFocus,
      sessions,
      minutes,
      mathTarget: Math.max(baseline.mathScore, mathTargets[index]),
      attendanceTarget: index < 4 ? 4 : 5,
      measurement,
    });
    if (index > 0 && measurement) {
      evaluation = evaluateFollowup(focus, baseline, previous, measurement);
      focus = evaluation.focus;
      previous = measurement;
    }
  }
  return { weeks, evaluation };
}
const data = $input.first().json;
if (data.statusCode === 200) {
  const roadmap = buildRoadmap(data.body.plan, data.current, data.checkpoints);
  data.body.roadmap = roadmap.weeks;
  if (roadmap.evaluation) data.body.evaluation = roadmap.evaluation;
}
return [{ json: { statusCode: data.statusCode, body: data.body } }];
